#!/bin/bash
# Synthetic lifecycle checks. Throughput, scale and endurance live in make performance-check.
set -euo pipefail
cd "$(dirname "$0")/.."
source scripts/toolchain.sh
swift build --build-tests
export SILLIES_METADATA_HELPER="$(swift build --show-bin-path)/SilliesWindowMetadata"
python3 -B scripts/run-checked-tests.py --timeout 90 --bin-path "$(swift build --show-bin-path)" --filter \
  'SpeechWindowTests|SpeechSchedulerTests|WindowSpeechChannelTests|SpeechWorkerExecutorTests|StreamingDiarizationTests|SpeakerAttributionTests|speakerActivity|diarization|transcriptionFailurePreserves|speechDiskBacklog|speechRecognition|audioCaptureClosure|audioRecoveryStatus|audioLifecycle|audioCaptureSequence|captureQueue|workspaceNotifications|workspaceFocusSequences|blockedUI|progressCoalescing|cancelledDelivery|repeatedAudioOverload|highChannelCountAudio|duplicateRecognizer|recognizerTimeout|cancellationRejects|partialRecognizer|sustainedAudioEncoding|trackingSchedule|dictationRestart|dictationQuit|dictationFinalization|dictationLateInsertion|dictationUses|dictationHistoryFailure|writingHistory|vaultListing|isolatedDictation|isolatedSelection|fieldEdit|vaultProtection|vaultRegeneration|vaultScreenshotRetry|vaultShowMore|backgroundRefreshesStay|vaultMissingUpdate|incrementalNotes|quittingFlushesField|vaultCursor|vaultInvalidation|vaultWriteBurst|vaultRetry|failedVaultIndex|vaultStartup|largeVaultPages|oversizedVaultBodies|vaultDetail|vaultDeletion|failedRecordUpdate|backgroundOCR|thousandsOfPendingNotes|cancelledVaultNotes|speechRegistry|downloadedSpeechProviders|chat|voice|Voice|playback|Playback|cancellingStalledVoice|explicitMemory|reviewedMemory|diagnostics|sharedIndexAdmission|sharedEmbedding|semanticDeadline|stoppingMemoryIndex|replacingEmbeddingProvider|vaultSemantic|closingTheBoundMeeting|metadataExactLookup|setup|Setup|directChat|directTalk|microphoneTrial|companionBackend|companionProfile|conversationAdmission|conversationIdeas|pendingQuestion|conversationSearchRejects|conversationReading|conversationUsability|clarificationEnds|clarificationPersistence|appleClarification|nativeClarification|malformedClarification|conversationDate|conversationExport|cancelledConversationExport|clearingHistoryDuringExport|talkClarification|selectedVaultRecords|acceptedProfileChanges|persistenceShutdown|pinnedFactWritesDrain|explicitContextAndMemoryControls|explicitVaultSelection|memorySearchDoesNot|personalFact|conversationDeletion|selectedBackground|pinnedFactsAreOmitted|contextRevisionRejects|vaultDiscussionFailure|unavailableNotesDoNotInterrupt|closingMeetingKeeps|audioSkillsRetain|audioSessionCompleted|modelActivity|modelCatalog|conversationReopening|stoppingTheCrew|accessibilityApplicationElements|accessibilityWindowInspection|roleCacheRejects'
